457: pub(crate) fn mounted_windows_path(path: &Path) -> Option<String> {
458:     let text = path.to_str()?;
459:     let remainder = text.strip_prefix("/mnt/")?;
460:     let bytes = remainder.as_bytes();
461:     if bytes.len() < 2 || !bytes[0].is_ascii_alphabetic() || bytes[1] != b'/' {
462:         return None;
463:     }
464:     let drive = (bytes[0] as char).to_ascii_uppercase();
465:     let tail = remainder[2..].replace('/', "\\");
466:     if tail.is_empty() {
467:         Some(format!("{drive}:\\"))
468:     } else {
469:         Some(format!("{drive}:\\{tail}"))
470:     }

